async get\_file\_type(file\_name: string): Promise {
 const file\_type\_extension = path.extname(file\_name).toLowerCase();

 if (
 file\_type\_extension === ".ejs" ||
 file\_type\_extension === ".handlebars"
 ) {
 return "template";
 } else if (file\_type\_extension === ".js") {
 return "js";
 } else if (file\_type\_extension === ".css") {
 return "css";
 } else if (
 file\_type\_extension === ".jpg" ||
 file\_type\_extension === ".jpeg" ||
 file\_type\_extension === ".png" ||
 file\_type\_extension === ".svg"
 ) {
 return "image";
 } else {
 return Promise.reject(
 new MoleculerClientError("File Type Error", 400, "FILE\_TYPE\_ERROR", {
 message: "file type is not valid",
 statusCode: 400,
 })
 );
 }
