 res.json();
 })
 .then((res: any) => {
 console.log(res);
 if (res?.code === 200) {
 navigation.goBack();
 } else {
 Alert.alert('Error', 'Please check Details !');
 }
 })
 .catch(err => console.log(err));
 };

 return (


